package io.xeros.solo;
import io.xeros.*;import io.xeros.content.minigames.toa.SoloToa;import io.xeros.content.minigames.tob.instance.TobInstance;import io.xeros.content.combat.npc.*;import io.xeros.model.*;import io.xeros.model.entity.npc.*;import io.xeros.model.entity.npc.actions.NPCHitPlayer;import io.xeros.model.entity.player.*;import java.util.*;
public final class RaidCombatSafetyCheck {
 static void ok(boolean b,String s){BossesPlayableCheck.ok(b,s);}static void exercise(int kind){Player p=ToaSoloPlayableCheck.actor();if(kind==0)SoloToa.enter(p);if(kind==1)TobInstance.enterSolo(p);if(kind==2)p.getMageArena().start();BossSpecialRoutesCheck.tick(p,1);NPC n=p.getInstance().getNpcs().stream().filter(v->!v.isUnregister()&&!v.isDead()).findFirst().orElseThrow();NPCAutoAttack a=n.getNpcAutoAttacks().get(0);ok(a.getAnimation()!=null,"Missing boss animation "+kind);int hp=p.getHealth().getCurrentHealth();for(int i=0;i<80&&p.getHealth().getCurrentHealth()==hp;i++)NPCHitPlayer.applyAutoAttackDamage(n,p,a);ok(p.getHealth().getCurrentHealth()<hp,"No native NPC damage "+kind);Arrays.fill(p.prayerActive,false);p.prayerActive[a.getCombatType()==CombatType.MAGE?16:a.getCombatType()==CombatType.RANGE?17:18]=true;hp=p.getHealth().getCurrentHealth();for(int i=0;i<10;i++)NPCHitPlayer.applyAutoAttackDamage(n,p,a);ok(p.getHealth().getCurrentHealth()==hp,"Prayer not protecting "+kind);Arrays.fill(p.prayerActive,false);n.lastX=n.absX;n.lastY=n.absY;p.underAttackByNpc=0;n.attack(p,a);p.getInstance().remove(p);hp=p.getHealth().getCurrentHealth();BossSpecialRoutesCheck.tick(p,6);for(int i=0;i<10;i++)NPCHitPlayer.applyAutoAttackDamage(n,p,a);ok(p.getHealth().getCurrentHealth()==hp,"Native delayed damage after instance exit "+kind);ToaSoloPlayableCheck.clear(p);}
 public static void main(String[]a)throws Exception{Thread.setDefaultUncaughtExceptionHandler((t,e)->{e.printStackTrace();System.exit(1);});Thread.currentThread().setName("GameThread");System.setProperty("solo.mode","true");System.setProperty("solo.xp","1");Server.startServerless();Configuration.BONUS_SKILL=-1;for(int k=0;k<3;k++)exercise(k);System.out.println("RAIDS_TOA_TOB_MAGE_ARENA_ATTACK_ANIMATIONS_NATIVE_INCOMING_DAMAGE_CORRECT_PRAYER_AND_QUEUED_HIT_EXIT_CANCELLATION_PASS");System.out.println("RAID_COMBAT_SAFETY_V65_PASS");System.exit(0);}
}
